<div class="page-title"><div><em>CARD CENTER</em><h1>Your cards</h1><p>Control your cards, limits and security.</p></div><button class="btn">+ Add a card</button></div><?php if(!$cards):?><div class="empty">No cards are linked to this account.</div><?php endif?><?php foreach($cards as $c):?><div class="grid card-grid"><article class="bank-card"><div><a class="brand brand-light"><i><b></b><b></b><b></b></i>North<span>West</span></a><strong><?=html_escape($c['network'])?></strong></div><i class="chip"></i><h3><?=html_escape($c['masked_number'])?></h3><footer><span><small>CARDHOLDER</small><?=html_escape($c['cardholder_name'])?></span><span><small>EXPIRES</small><?=sprintf('%02d/%02d',$c['expiry_month'],$c['expiry_year']%100)?></span></footer></article><section class="panel controls"><h2>Card controls</h2><?php $controls=array('is_frozen'=>array('▣','Freeze card','Temporarily block all transactions'),'international_enabled'=>array('◎','International payments','Allow purchases outside the US'),'online_enabled'=>array('▤','Online payments','Allow online and in-app purchases'));foreach($controls as $field=>$info):?><form method="post" action="<?=site_url('cards/'.$c['id'].'/toggle')?>"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="field" value="<?=$field?>"><i><?=$info[0]?></i><div><b><?=$info[1]?></b><small><?=$info[2]?></small></div><button class="switch <?=$c[$field]?'on':''?>"><i></i></button></form><?php endforeach?></section></div><?php endforeach?>
